// Проблема: easy to mix up
fn set_age(age: u32) {}
fn set_id(id: u32) {}
set_age(42); // Ошибка не поймается

// Решение: Newtype
struct UserId(u64);
struct Age(u8);

fn set_age(age: Age) {}
fn set_id(id: UserId) {}

fn main() {
    let id = UserId(42);
    let age = Age(30);
    set_id(id);
    set_age(age);
    // set_id(age); // ОШИБКА: mismatched types
}

use std::ops::{Add, Deref};

struct Meters(f64);

impl Deref for Meters {
    type Target = f64;
    fn deref(&self) -> &f64 { &self.0 }
}

impl Add for Meters {
    type Output = Meters;
    fn add(self, other: Meters) -> Meters {
        Meters(self.0 + other.0)
    }
}

fn main() {
    let a = Meters(10.0);
    let b = Meters(5.0);
    let c = a + b; // Meters(15.0)
    println!("{}", *c); // Deref -> f64
}

